def supports_measurement(vector):
    value=np.asarray(vector,dtype=np.float32)
    if value.shape!=(512,) or not np.isfinite(value).all():return False
    norm=float(np.linalg.norm(value))
    if norm<=0:return False
    value=value/norm
    return bool(float(np.max(_MEASUREMENT@value))>max(float(np.max(_OBJECT@value)),float(np.max(_GARDEN@value))))
